    /// <summary>
    /// Modify based on the user selected InventLocation
    /// </summary>
    /// <param name="sender">Form datasource</param>
    /// <param name="e">Data field</param>
    [FormDataFieldEventHandler(formDataFieldStr(SalesTable, InventDim, InventSiteId), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void SalesInventSiteId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun formRun = sender.datasource().formRun();
       
        InventDim inventDim = formRun.dataSource(formdatasourcestr(SalesTable, InventDim)).cursor();
        SalesLine salesLine = formRun.dataSource(formdatasourcestr(SalesTable, SalesLine)).cursor();

        if (inventDim.InventLocationId)
        {
            salesLine.DefaultDimension = InventLocation::changeDimension(salesLine.DefaultDimension, inventDim.InventLocationId);
        }
        else
        {
            salesLine.DefaultDimension = InventSite::changeDimension(salesLine.DefaultDimension, InventSite::find(inventDim.InventSiteId).SiteId);
        }
    }

    /// <summary>
    /// Modify based on the user selected InventLocation 
    /// </summary>
    /// <param name="sender">Form datasource</param>
    /// <param name="e">Data field</param>
    [FormDataFieldEventHandler(formDataFieldStr(PurchTable, InventDim, InventLocationId), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventLocationId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun formRun = sender.datasource().formRun();

        InventDim inventDim = formRun.dataSource(formdatasourcestr(PurchTable, InventDim)).cursor();
        PurchLine purchLine = formRun.dataSource(formdatasourcestr(PurchTable, PurchLine)).cursor();

        if (inventDim.InventLocationId)
        {
            purchLine.DefaultDimension = InventLocation::changeDimension(purchLine.DefaultDimension, inventDim.InventLocationId);
        }

        DimensionDisplayValue dimensionValue = METInventJournalEventHandler::getDimensionDisplayValue(purchLine.DefaultDimension, METConstants::profitCentre);
        if(!dimensionValue || !inventDim.InventLocationId)
        {
            purchLine.DefaultDimension = InventSite::changeDimension(purchLine.DefaultDimension, InventSite::find(inventDim.InventSiteId).SiteId);
        }


    }

